artifacts.content:
{"files": {"main_tf": "terraform {
  required_providers {
    oci = {
      source = "oracle/oci"
      version = ">= 4.0.0"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

provider "oci" {
  region = var.region
}

data "oci_identity_tenancy" "tenancy" {
}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.compartment_ocid
}

data "oci_core_images" "ol8" {
  compartment_id = var.compartment_ocid
  operating_system = "Oracle Linux"
  operating_system_version = "8"
  shapes = ["VM.Standard.E5.Flex"]
  state = "AVAILABLE"
  sort_by = "TIMECREATED"
  sort_order = "DESC"
}

data "oci_core_services" "oci_services" {
}

data "oci_objectstorage_namespace" "ns" {
}

data "oci_core_volume_backup_policies" "backup_policies" {
}

resource "oci_core_vcn" "vcn" {
  compartment_id = var.compartment_ocid
  cidr_block     = "10.0.0.0/16"
  display_name   = var.prefix != "" ? "${var.prefix}-vcn" : "vcn"
  dns_label      = var.prefix != "" ? lower(replace(var.prefix, "_", "-")) : "vcn"
  freeform_tags = {
    "dyn-group" = "northwind-network"
  }
}

resource "oci_core_internet_gateway" "igw" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-igw" : "igw"
}

resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-public-rt" : "public-rt"

  route_rules {
    description       = "Internet Gateway"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_internet_gateway.igw.id
  }
}

resource "oci_core_service_gateway" "svc_gw" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-svc-gw" : "svc-gw"

  services {
    service_id = data.oci_core_services.oci_services.services.0.id
  }
}

resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-private-rt" : "private-rt"

  route_rules {
    description       = "OCI Services"
    destination_type  = "SERVICE_CIDR_BLOCK"
    destination       = "all-oci-private-ips"
    network_entity_id = oci_core_service_gateway.svc_gw.id
  }
}

resource "oci_core_subnet" "public" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.1.0/24"
  display_name                = var.prefix != "" ? "${var.prefix}-public-subnet" : "public-subnet"
  dns_label                   = "public"
  route_table_id              = oci_core_route_table.public_rt.id
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp
  prohibit_public_ip_on_vnic  = false
  freeform_tags = {
    "dyn-group" = "northwind-network"
  }
}

resource "oci_core_subnet" "web" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = data.oci_identity_availability_domains.ads.availability_domains.0.name
  cidr_block                  = "10.0.10.0/24"
  display_name                = var.prefix != "" ? "${var.prefix}-web-subnet" : "web-subnet"
  dns_label                   = "web"
  route_table_id              = oci_core_route_table.private_rt.id
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp
  prohibit_public_ip_on_vnic  = true
  freeform_tags = {
    "dyn-group" = "northwind-network"
  }
}

resource "oci_core_subnet" "app" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = data.oci_identity_availability_domains.ads.availability_domains.0.name
  cidr_block                  = "10.0.11.0/24"
  display_name                = var.prefix != "" ? "${var.prefix}-app-subnet" : "app-subnet"
  dns_label                   = "app"
  route_table_id              = oci_core_route_table.private_rt.id
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp
  prohibit_public_ip_on_vnic  = true
  freeform_tags = {
    "dyn-group" = "northwind-network"
  }
}

resource "oci_core_subnet" "db" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = data.oci_identity_availability_domains.ads.availability_domains.0.name
  cidr_block                  = "10.0.12.0/24"
  display_name                = var.prefix != "" ? "${var.prefix}-db-subnet" : "db-subnet"
  dns_label                   = "db"
  route_table_id              = oci_core_route_table.private_rt.id
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp
  prohibit_public_ip_on_vnic  = true
  freeform_tags = {
    "dyn-group" = "northwind-network"
  }
}

resource "oci_core_network_security_group" "bastion_nsg" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-bastion-nsg" : "bastion-nsg"
}

resource "oci_core_network_security_group" "lb_nsg" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-lb-nsg" : "lb-nsg"
}

resource "oci_core_network_security_group" "web_nsg" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-web-nsg" : "web-nsg"
}

resource "oci_core_network_security_group" "app_nsg" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-app-nsg" : "app-nsg"
}

resource "oci_core_network_security_group" "db_nsg" {
  compartment_id = var.compartment_ocid
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = var.prefix != "" ? "${var.prefix}-db-nsg" : "db-nsg"
}

# Bastion NSG rules
resource "oci_core_network_security_group_security_rule" "bastion_ssh" {
  network_security_group_id = oci_core_network_security_group.bastion_nsg.id

  direction         = "INGRESS"
  protocol          = "6"
  source            = "0.0.0.0/0"
  source_type       = "CIDR_BLOCK"
  tcp_options {
    destination_port_range {
      max = 22
      min = 22
    }
  }
}

resource "oci_core_network_security_group_security_rule" "bastion_egress" {
  network_security_group_id = oci_core_network_security_group.bastion_nsg.id

  direction       = "EGRESS"
  destination     = "0.0.0.0/0"
  destination_type = "CIDR_BLOCK"
  protocol        = "all"
}

# LB NSG rules
resource "oci_core_network_security_group_security_rule" "lb_http_ingress" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id

  direction   = "INGRESS"
  protocol    = "6"
  source      = "0.0.0.0/0"
  source_type = "CIDR_BLOCK"
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_web_egress" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id

  direction         = "EGRESS"
  destination       = oci_core_subnet.web.cidr_block
  destination_type  = "CIDR_BLOCK"
  protocol          = "6"
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_all" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id

  direction       = "EGRESS"
  destination     = "0.0.0.0/0"
  destination_type = "CIDR_BLOCK"
  protocol        = "all"
}

# Web NSG rules
resource "oci_core_network_security_group_security_rule" "web_lb_ingress" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id

  direction   = "INGRESS"
  protocol    = "6"
  source      = oci_core_network_security_group.lb_nsg.id
  source_type = "NSG"
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_app_egress" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id

  direction         = "EGRESS"
  destination       = oci_core_subnet.app.cidr_block
  destination_type  = "CIDR_BLOCK"
  protocol          = "6"
  tcp_options {
    destination_port_range {
      max = 8080
      min = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_all" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id

  direction       = "EGRESS"
  destination     = "0.0.0.0/0"
  destination_type = "CIDR_BLOCK"
  protocol        = "all"
}

# App NSG rules
resource "oci_core_network_security_group_security_rule" "app_web_ingress" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id

  direction   = "INGRESS"
  protocol    = "6"
  source      = oci_core_network_security_group.web_nsg.id
  source_type = "NSG"
  tcp_options {
    destination_port_range {
      max = 8080
      min = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_db_egress" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id

  direction         = "EGRESS"
  destination       = oci_core_subnet.db.cidr_block
  destination_type  = "CIDR_BLOCK"
  protocol          = "6"
  tcp_options {
    destination_port_range {
      max = 1521
      min = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_all" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id

  direction       = "EGRESS"
  destination     = "0.0.0.0/0"
  destination_type = "CIDR_BLOCK"
  protocol        = "all"
}

# DB NSG rules
resource "oci_core_network_security_group_security_rule" "db_app_ingress" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id

  direction   = "INGRESS"
  protocol    = "6"
  source      = oci_core_network_security_group.app_nsg.id
  source_type = "NSG"
  tcp_options {
    destination_port_range {
      max = 1521
      min = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "db_egress_all" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id

  direction       = "EGRESS"
  destination     = "0.0.0.0/0"
  destination_type = "CIDR_BLOCK"
  protocol        = "all"
}

# Vault / KMS
resource "oci_kms_vault" "vault" {
  compartment_id = var.compartment_ocid
  display_name   = var.prefix != "" ? "${var.prefix}-kms-vault" : "kms-vault"
  compartment_id = var.compartment_ocid
}

resource "oci_kms_key" "master_key" {
  management_endpoint       = oci_kms_vault.vault.management_endpoint
  display_name              = var.prefix != "" ? "${var.prefix}-master-key" : "master-key"
  compartment_id            = var.compartment_ocid
  vault_id                  = oci_kms_vault.vault.id
  length                    = 32
  algorithm                 = "AES"
  curve_id                  = ""
  protection_mode           = "HSM"
  key_type                  = "HKMS"
}

# Object Storage
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "oci_objectstorage_bucket" "bucket" {
  compartment_id = var.compartment_ocid
  namespace      = data.oci_objectstorage_namespace.ns.namespace
  name           = lower("${var.prefix}health${random_string.bucket_suffix.result}")
  kms_key_id     = oci_kms_key.master_key.id
  public_access_type = "NoPublicAccess"
}

# Logging
resource "oci_logging_log_group" "log_group" {
  compartment_id = var.compartment_ocid
  display_name   = var.prefix != "" ? "${var.prefix}-log-group" : "log-group"
}

# Monitoring example alarm
resource "oci_monitoring_alarm" "cpu_high" {
  compartment_id         = var.compartment_ocid
  display_name           = var.prefix != "" ? "${var.prefix}-cpu-high" : "cpu-high"
  metric_compartment_id  = var.compartment_ocid
  namespace              = "oci_computeagent"
  query                  = "CpuUtilization[5m].maximum() > 80"
  severity               = "CRITICAL"
  destinations {
    destination_type = "LOGGING"
    log_group_id     = oci_logging_log_group.log_group.id
  }
}

# IAM Dynamic Group and Policy
resource "oci_identity_dynamic_group" "compute_dg" {
  compartment_id = var.tenancy_ocid
  name           = var.prefix != "" ? "${var.prefix}-compute-dg" : "compute-dg"
  matching_rule  = "ALL {resource.type = 'instance', tag.dyn-group = 'northwind-compute'} UNION {resource.type = 'autonomousdatabase', tag.dyn-group = 'northwind-compute'} UNION {resource.type = 'loadbalancer', tag.dyn-group = 'northwind-compute' }"
}

resource "oci_identity_policy" "compute_policy" {
  depends_on = [oci_identity_dynamic_group.compute_dg]
  compartment_id = var.compartment_ocid
  name         = var.prefix != "" ? "${var.prefix}-compute-policy" : "compute-policy"
  description  = "Policy for Northwind compute resources"
  statements = [
    "Allow dynamic-group ${oci_identity_dynamic_group.compute_dg.name} to read log-groups in compartment id '${var.compartment_ocid}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.compute_dg.name} to read log-content in compartment id '${var.compartment_ocid}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.compute_dg.name} to read metrics in tenancy",
    "Allow dynamic-group ${oci_identity_dynamic_group.compute_dg.name} to read object-family in compartment id '${var.compartment_ocid}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.compute_dg.name} to manage kms-crypto-endpoint-family in compartment id '${var.compartment_ocid}'",
  ]
}

# Bastion Instance
resource "oci_core_instance" "bastion" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-bastion" : "bastion"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 1
    memory_in_gbs = 1
  }

  create_vnic_details {
    subnet_id        = oci_core_subnet.public.id
    nsg_ids          = [oci_core_network_security_group.bastion_nsg.id]
    assign_public_ip = true
  }

  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

# Web Tier Instances
resource "oci_core_instance" "web1" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-web1" : "web1"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 2
    memory_in_gbs = 16
  }

  create_vnic_details {
    subnet_id        = oci_core_subnet.web.id
    nsg_ids          = [oci_core_network_security_group.web_nsg.id]
    assign_public_ip = false
    fault_domain     = "FAULT-DOMAIN-1"
  }

  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

resource "oci_core_instance" "web2" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-web2" : "web2"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 2
    memory_in_gbs = 16
  }

  create_vnic_details {
    subnet_id        = oci_core_subnet.web.id
    nsg_ids          = [oci_core_network_security_group.web_nsg.id]
    assign_public_ip = false
    fault_domain     = "FAULT-DOMAIN-2"
  }

  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

# App Tier Instances and Block Volumes
resource "oci_core_volume" "app1_volume" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-app1-volume" : "app1-volume"
  size_in_gbs         = var.block_storage_gb / 2
  vpus_per_gb         = 20
  kms_key_id          = oci_kms_key.master_key.id
  backup_policy_id    = data.oci_core_volume_backup_policies.backup_policies.volume_backup_policies[0]["id"]
}

resource "oci_core_volume_attachment" "app1_volume_attachment" {
  instance_id = oci_core_instance.app1.id
  volume_id   = oci_core_volume.app1_volume.id
}

resource "oci_core_volume" "app2_volume" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-app2-volume" : "app2-volume"
  size_in_gbs         = var.block_storage_gb / 2
  vpus_per_gb         = 20
  kms_key_id          = oci_kms_key.master_key.id
  backup_policy_id    = data.oci_core_volume_backup_policies.backup_policies.volume_backup_policies[0]["id"]
}

resource "oci_core_volume_attachment" "app2_volume_attachment" {
  instance_id = oci_core_instance.app2.id
  volume_id   = oci_core_volume.app2_volume.id
}

resource "oci_core_instance" "app1" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-app1" : "app1"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 4
    memory_in_gbs = 32
  }

  create_vnic_details {
    subnet_id        = oci_core_subnet.app.id
    nsg_ids          = [oci_core_network_security_group.app_nsg.id]
    assign_public_ip = false
    fault_domain     = "FAULT-DOMAIN-1"
  }

  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

resource "oci_core_instance" "app2" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains.0.name
  compartment_id      = var.compartment_ocid
  display_name        = var.prefix != "" ? "${var.prefix}-app2" : "app2"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 4
    memory_in_gbs = 32
  }

  create_vnic_details {
    subnet_id        = oci_core_subnet.app.id
    nsg_ids          = [oci_core_network_security_group.app_nsg.id]
    assign_public_ip = false
    fault_domain     = "FAULT-DOMAIN-2"
  }

  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

# Database - Autonomous Database for managed HA
resource "oci_database_autonomous_database" "db" {
  compartment_id        = var.compartment_ocid
  cpu_core_count        = 4
  data_storage_size_in_tbs = 1
  db_name               = upper(var.prefix != "" ? replace(var.prefix, "-", "") : "NORTHWIN")
  display_name          = var.prefix != "" ? "${var.prefix}-health-db" : "health-db"
  admin_password        = var.db_admin_password
  license_model         = "LICENSE_INCLUDED"
  db_workload           = "OLTP"
  is_dedicated          = false
  is_preview            = false
  subnet_id             = oci_core_subnet.db.id
  nsg_ids               = [oci_core_network_security_group.db_nsg.id]
  private_endpoint_label = "private"
  whitelisted_ips       = []

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }

  data_safety_regulation_compliance = "BASIC"
}

# Load Balancer
resource "oci_load_balancer_load_balancer" "lb" {
  compartment_id = var.compartment_ocid
  display_name   = var.prefix != "" ? "${var.prefix}-lb" : "lb"
  shape = "FLEXIBLE"

  shape_details {
    minimum_bandwidth_in_gbps = 10
    maximum_bandwidth_in_gbps = 100
    ocpu  = 1
    memory_in_gbs = 1
  }

  subnet_ids = [oci_core_subnet.public.id]
  network_security_group_ids = [oci_core_network_security_group.lb_nsg.id]

  freeform_tags = {
    "dyn-group" = "northwind-compute"
  }
}

resource "oci_load_balancer_backend_set" "web_backend" {
  load_balancer_id = oci_load_balancer_load_balancer.lb.id
  name             = "web_backend"
  policy           = "ROUND_ROBIN"

  health_checker {
    interval_in_millis = 10000
    port               = 80
    protocol           = "TCP"
    retries            = 3
    timeout_in_millis  = 3000
  }
}

resource "oci_load_balancer_listener" "http_listener" {
  load_balancer_id         = oci_load_balancer_load_balancer.lb.id
  name                     = "http_listener"
  default_backend_set_name = oci_load_balancer_backend_set.web_backend.name
  port                     = 80
  protocol                 = "HTTP"
}

# WAF
resource "oci_waf_waf" "waf" {
  compartment_id = var.compartment_ocid
  display_name   = var.prefix != "" ? "${var.prefix}-waf" : "waf"
}

resource "oci_waf_waf_policy" "waf_policy" {
  compartment_id = var.compartment_ocid
  display_name   = var.prefix != "" ? "${var.prefix}-waf-policy" : "waf-policy"
  waf_id         = oci_waf_waf.waf.id

  actions {
    type = "BLOCK"
    block_action {
      block_code = "BLOCK_DEFAULT_403"
      block_reason = "Protection violated"
    }
  }
  # Default protection rules enabled
  protection_capabilities {
    is_media_firewall_enabled = true
  }
}
