artifacts.content:
{"files": {"main_tf": "terraform {
  required_providers {
    oci = {
      source = "oracle/oci"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

provider "oci" {
  tenancy_ocid         = var.tenancy_ocid
  user_ocid            = var.user_ocid
  fingerprint          = var.fingerprint
  private_key_content  = var.private_key_content
  region               = var.region
}

provider "random" {}

data "oci_identity_tenancy" "tenant" {
  tenancy_id = var.tenancy_ocid
}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.compartment_id
}

data "oci_core_images" "ol8" {
  compartment_id = var.compartment_id
  operating_system        = "Oracle Linux"
  operating_system_version = "8.0"
  state                   = "AVAILABLE"
  shape                   = "VM.Standard.E5.Flex"

  filter {
    name   = "display_name"
    values = ["^.*-oraclelinux-8.*"]
    regex  = true
  }
}

data "oci_core_services" "oci_services" {
  filter {
    name   = "name"
    values = ["All OCI Services in Oracle Services Network"]
  }
}

data "oci_objectstorage_namespace" "ns" {
  compartment_id = var.compartment_id
}

data "oci_database_db_versions" "db_versions" {
  compartment_id = var.compartment_id
  engine         = "DB"
}

locals {
  ad_names = [for ad in data.oci_identity_availability_domains.ads.availability_domains : ad.name]
  prefix   = "northwind-${var.environment}-"
  web_instance_ocids  = [oci_core_instance.web[0].id, oci_core_instance.web[1].id]
  app_instance_ocids  = [oci_core_instance.app[0].id, oci_core_instance.app[1].id]
}

# Vault
resource "oci_kms_vault" "vault" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}vault"
  vault_type     = "VIRTUAL"
}

resource "oci_kms_key" "master_key" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}master-key"
  vault_id       = oci_kms_vault.vault.id

  key_shape {
    algorithm = "AES"
    length    = 32
  }
}

# VCN and Networking
resource "oci_core_vcn" "vcn" {
  compartment_id = var.compartment_id
  cidr_block     = "10.0.0.0/16"
  display_name   = "${local.prefix}vcn"
  dns_label      = replace(local.prefix, "-", "")
}

resource "oci_core_internet_gateway" "igw" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}igw"
  vcn_id         = oci_core_vcn.vcn.id
}

resource "oci_core_nat_gateway" "nat" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}nat"
  vcn_id         = oci_core_vcn.vcn.id
}

resource "oci_core_service_gateway" "svc_gw" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id

  services {
    service_id = data.oci_core_services.oci_services.services[0].id
  }
}

resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.prefix}public-rt"

  route_rules {
    description       = "IGW"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_internet_gateway.igw.id
  }
}

resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.prefix}private-rt"

  route_rules {
    description       = "NAT"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_nat_gateway.nat.id
  }
  route_rules {
    description       = "OCI Services"
    destination       = "all-oci-private-ips-ipv4"
    destination_type  = "SERVICE_CIDR_BLOCK"
    network_entity_id = oci_core_service_gateway.svc_gw.id
  }
}

resource "oci_core_subnet" "public" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  cidr_block     = "10.0.0.0/27"
  display_name   = "${local.prefix}public"
  dns_label      = "public"
  route_table_id = oci_core_route_table.public_rt.id
  prohibit_public_ip_on_vnic = false
}

resource "oci_core_subnet" "web" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  cidr_block     = "10.0.1.0/26"
  display_name   = "${local.prefix}web"
  dns_label      = "web"
  route_table_id = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
}

resource "oci_core_subnet" "app" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  cidr_block     = "10.0.1.64/26"
  display_name   = "${local.prefix}app"
  dns_label      = "app"
  route_table_id = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
}

resource "oci_core_subnet" "db" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  cidr_block     = "10.0.1.128/26"
  display_name   = "${local.prefix}db"
  dns_label      = "db"
  route_table_id = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
}

# NSGs
resource "oci_core_network_security_group" "lb_nsg" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}lb-nsg"
}

resource "oci_core_network_security_group" "web_nsg" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}web-nsg"
}

resource "oci_core_network_security_group" "app_nsg" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}app-nsg"
}

resource "oci_core_network_security_group" "db_nsg" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}db-nsg"
}

# NSG Rules
resource "oci_core_network_security_group_security_rule" "lb_ingress_80" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction = "INGRESS"
  protocol  = "6"
  source    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_ingress_443" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction = "INGRESS"
  protocol  = "6"
  source    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      min = 443
      max = 443
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_web" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction = "EGRESS"
  protocol  = "6"
  destination = oci_core_subnet.web.cidr_block
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_ingress_lb" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction = "INGRESS"
  protocol  = "6"
  source    = oci_core_subnet.public.cidr_block
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_app" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction = "EGRESS"
  protocol  = "6"
  destination = oci_core_subnet.app.cidr_block
  tcp_options {
    destination_port_range {
      min = 8080
      max = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_ingress_web" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction = "INGRESS"
  protocol  = "6"
  source    = oci_core_subnet.web.cidr_block
  tcp_options {
    destination_port_range {
      min = 8080
      max = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_db" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction = "EGRESS"
  protocol  = "6"
  destination = oci_core_subnet.db.cidr_block
  tcp_options {
    destination_port_range {
      min = 1521
      max = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "db_ingress_app" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id
  direction = "INGRESS"
  protocol  = "6"
  source    = oci_core_subnet.app.cidr_block
  tcp_options {
    destination_port_range {
      min = 1521
      max = 1521
    }
  }
}

# Egress for all private tiers to OCI services and internet via NAT
resource "oci_core_network_security_group_security_rule" "private_egress_oci" {
  count                   = 3
  network_security_group_id = [oci_core_network_security_group.web_nsg.id, oci_core_network_security_group.app_nsg.id, oci_core_network_security_group.db_nsg.id][count.index]
  direction               = "EGRESS"
  protocol                = "all"
  destination             = "all-oci-private-ips-ipv4"
  destination_type        = "SERVICE_CIDR_BLOCK"
}

resource "oci_core_network_security_group_security_rule" "private_egress_internet" {
  count                   = 3
  network_security_group_id = [oci_core_network_security_group.web_nsg.id, oci_core_network_security_group.app_nsg.id, oci_core_network_security_group.db_nsg.id][count.index]
  direction               = "EGRESS"
  protocol                = "all"
  destination             = "0.0.0.0/0"
}

# Web Tier Instances
resource "oci_core_instance" "web" {
  count               = 2
  compartment_id      = var.compartment_id
  availability_domain = local.ad_names[count.index % 2]
  display_name        = "${local.prefix}web-${count.index + 1}"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 2
    memory_in_gbs = 16
  }

  create_vnic_details {
    subnet_id = oci_core_subnet.web.id
    nsg_ids   = [oci_core_network_security_group.web_nsg.id]
    display_name = "${local.prefix}web-vnic-${count.index + 1}"
  }

  source_details {
    source_type = "image"
    source_id   = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
    user_data = base64encode("#!/bin/bash\nyum update -y\nyum install -y dotnet-sdk-8.0")  # Basic .NET setup
  }
}

# App Tier Instances
resource "oci_core_instance" "app" {
  count               = 2
  compartment_id      = var.compartment_id
  availability_domain = local.ad_names[count.index % 2]
  display_name        = "${local.prefix}app-${count.index + 1}"
  shape               = "VM.Standard.E5.Flex"

  shape_config {
    ocpus         = 4
    memory_in_gbs = 32
  }

  create_vnic_details {
    subnet_id = oci_core_subnet.app.id
    nsg_ids   = [oci_core_network_security_group.app_nsg.id]
    display_name = "${local.prefix}app-vnic-${count.index + 1}"
  }

  source_details {
    source_type = "image"
    source_id   = data.oci_core_images.ol8.images[0].id
  }

  metadata = {
    ssh_authorized_keys = var.ssh_public_key
    user_data = base64encode("#!/bin/bash\nyum update -y\nyum install -y dotnet-sdk-8.0")  # Basic .NET app setup
  }
}

# Block Volumes for App (500GB total)
resource "oci_core_volume" "app_volume" {
  count               = 2
  compartment_id      = var.compartment_id
  availability_domain = local.ad_names[count.index % 2]
  display_name        = "${local.prefix}app-vol-${count.index + 1}"
  size_in_gbs         = 250
  kms_key_id          = oci_kms_key.master_key.id
}

resource "oci_core_volume_attachment" "app_volume_attachment" {
  count          = 2
  attachment_type = "paravirtualized"
  instance_id    = oci_core_instance.app[count.index].id
  volume_id      = oci_core_volume.app_volume[count.index].id
}

# Flexible Load Balancer
resource "oci_load_balancer_load_balancer" "lb" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}lb"
  shape          = "flexible"

  shape_details {
    minimum_bandwidth_in_mbps = 10
    maximum_bandwidth_in_mbps = 400
  }

  subnet_ids              = [oci_core_subnet.public.id]
  network_security_group_ids = [oci_core_network_security_group.lb_nsg.id]

  freeform_tags = {
    "poc" = "true"
  }
}

resource "oci_load_balancer_backend_set" "web_backend" {
  load_balancer_id = oci_load_balancer_load_balancer.lb.id
  name             = "web-backend"
  policy           = "ROUND_ROBIN"

  health_checker {
    interval_in_secs         = 10
    port                     = 80
    protocol                 = "HTTP"
    url_path                 = "/health"
    healthy_threshold        = 2
    unhealthy_threshold      = 2
    timeout_in_secs          = 3
    return_code              = 200
    require_repeated_headers = false
  }
}

resource "oci_load_balancer_backend" "web_backend" {
  count           = 2
  load_balancer_id = oci_load_balancer_load_balancer.lb.id
  backendset_name = oci_load_balancer_backend_set.web_backend.name
  ip_address      = oci_core_instance.web[count.index].private_ip
  port            = 80
  backup          = false
  drain           = false
  offline         = false
  weight          = 1
}

resource "oci_load_balancer_listener" "http_listener" {
  load_balancer_id         = oci_load_balancer_load_balancer.lb.id
  name                     = "http"
  default_backend_set_name = oci_load_balancer_backend_set.web_backend.name
  protocol                 = "HTTP"
  port                     = "80"
}

# WAF
resource "oci_waf_web_app_firewall_policy" "waf_policy" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}waf-policy"
}

resource "oci_waf_web_app_firewall_association" "waf_assoc" {
  web_app_firewall_id = oci_waf_web_app_firewall_policy.waf_policy.id
  load_balancer_id    = oci_load_balancer_load_balancer.lb.id
}

# Database
resource "oci_database_db_system" "db" {
  compartment_id = var.compartment_id

  availability_domain = local.ad_names[0]
  shape               = "VM.Standard.E5.Flex"
  display_name        = "${local.prefix}db"
  subnet_id           = oci_core_subnet.db.id
  nsg_ids             = [oci_core_network_security_group.db_nsg.id]
  hostname_label      = "dbhost"
  domain              = "${replace(local.prefix, "-", "")}oraclevcn.com"

  ssh_public_keys = [var.ssh_public_key]

  admin_password = var.db_admin_password

  data_storage_size_in_gbs = 500
  license_model           = "LICENSE_INCLUDED"
  node_count              = 2
  cluster_name            = "${local.prefix}cluster"

  shape_config {
    ocpus         = 4
    memory_in_gbs = 64
  }

  db_home {
    database_version = data.oci_database_db_versions.db_versions.db_versions[0].version
  }

  freeform_tags = {
    "poc" = "true"
  }
}

# Object Storage
resource "random_string" "bucket_suffix" {
  length  = 10
  special = false
  upper   = false
}

resource "oci_objectstorage_bucket" "backups" {
  compartment_id = var.compartment_id
  namespace      = data.oci_objectstorage_namespace.ns.namespace
  name           = "${local.prefix}backups-${random_string.bucket_suffix.result}"
  kms_key_id     = oci_kms_key.master_key.id
  public_access_type = "NoPublicAccess"
}

# Logging & Monitoring
resource "oci_logging_log_group" "logs" {
  compartment_id = var.compartment_id
  display_name   = "${local.prefix}logs"
}

# IAM Dynamic Groups & Policies
resource "oci_identity_dynamic_group" "web_dg" {
  compartment_id = var.compartment_id
  name           = "${local.prefix}web-dg"
  matching_rule  = "resource.ocid = '${local.web_instance_ocids[0]}' OR resource.ocid = '${local.web_instance_ocids[1]}'"
}

resource "oci_identity_dynamic_group" "app_dg" {
  compartment_id = var.compartment_id
  name           = "${local.prefix}app-dg"
  matching_rule  = "resource.ocid = '${local.app_instance_ocids[0]}' OR resource.ocid = '${local.app_instance_ocids[1]}'"
}

resource "oci_identity_policy" "instances_policy" {
  depends_on = [oci_identity_dynamic_group.web_dg, oci_identity_dynamic_group.app_dg]
  compartment_id = var.compartment_id
  name        = "${local.prefix}instances-policy"
  description = "Allow instances access to services for HIPAA compliance"

  statements = [
    "Allow dynamic-group ${oci_identity_dynamic_group.web_dg.name} to read object-family in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.web_dg.name} to read log-content in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.web_dg.name} to use kms-family in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.app_dg.name} to read object-family in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.app_dg.name} to read log-content in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.app_dg.name} to use kms-family in compartment id '${var.compartment_id}'",
    "Allow dynamic-group ${oci_identity_dynamic_group.app_dg.name} to manage database-family in compartment id '${var.compartment_id}'",
    "Allow service ${oci_load_balancer_load_balancer.lb.id} to manage object-family in compartment id '${var.compartment_id}'",
  ]
}
