artifacts.content:
{"files": {"main_tf": "terraform {
  required_version = ">= 1.5"
  required_providers {
    oci = {
      source  = "oracle/oci"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "oci" {
  region = var.region
}

provider "random" {}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.compartment_id
}

data "oci_objectstorage_namespace" "ns" {
  compartment_id = var.compartment_id
}

data "oci_core_images" "ol_image" {
  compartment_id = var.compartment_id
  operating_system = "Oracle Linux"
  operating_system_version = "8.0"
  state = "AVAILABLE"
  filter {
    name   = "display_name"
    values = ["Oracle-Linux-8.*"]
    regex  = true
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "oci_core_vcn" "vcn" {
  compartment_id = var.compartment_id
  cidr_block     = "10.0.0.0/16"
  display_name   = "${var.label_prefix}-vcn"
  dns_label      = "northwind"
}

resource "oci_core_internet_gateway" "igw" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  enabled        = true
  display_name   = "${var.label_prefix}-igw"
}

resource "oci_core_nat_gateway" "nat" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-nat"
}

resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-public-rt"
  route_rules {
    network_entity_id = oci_core_internet_gateway.igw.id
    destination       = "0.0.0.0/0"
  }
}

resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-private-rt"
  route_rules {
    network_entity_id = oci_core_nat_gateway.nat.id
    destination       = "0.0.0.0/0"
  }
}

resource "oci_core_security_list" "public_sl" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-public-sl"
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "all"
  }
  egress_security_rules {
    destination = "10.0.0.0/16"
    protocol    = "all"
  }
  ingress_security_rules {
    protocol = "1"
    source   = "10.0.0.0/16"
    icmp_options {
      type = "3"
      code = "4"
    }
  }
  ingress_security_rules {
    protocol = "6"
    source   = "0.0.0.0/0"
    tcp_options {
      min = 80
      max = 80
    }
  }
  ingress_security_rules {
    protocol = "6"
    source   = "0.0.0.0/0"
    tcp_options {
      min = 443
      max = 443
    }
  }
  ingress_security_rules {
    protocol = "all"
    source   = "10.0.0.0/16"
  }
}

resource "oci_core_security_list" "private_sl" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-private-sl"
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "6"
    tcp_options {
      min = 80
      max = 80
    }
  }
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "6"
    tcp_options {
      min = 443
      max = 443
    }
  }
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "17"
    udp_options {
      min = 53
      max = 53
    }
  }
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "17"
    udp_options {
      min = 123
      max = 123
    }
  }
  egress_security_rules {
    destination = "0.0.0.0/0"
    protocol    = "6"
    tcp_options {
      min = 22
      max = 22
    }
  }
  egress_security_rules {
    destination = "10.0.0.0/16"
    protocol    = "all"
  }
  ingress_security_rules {
    protocol = "6"
    source   = var.admin_cidr
    tcp_options {
      min = 22
      max = 22
    }
  }
  ingress_security_rules {
    protocol = "1"
    source   = "10.0.0.0/16"
    icmp_options {
      type = "3"
      code = "4"
    }
  }
  ingress_security_rules {
    protocol = "all"
    source   = "10.0.0.0/16"
  }
}

resource "oci_core_subnet" "public_lb" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.0.0/24"
  display_name                = "${var.label_prefix}-public-lb"
  route_table_id              = oci_core_route_table.public_rt.id
  security_list_ids           = [oci_core_security_list.public_sl.id]
  prohibit_public_ip_on_vnic  = false
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp_options_id
}

resource "oci_core_subnet" "web" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.1.0/24"
  display_name                = "${var.label_prefix}-web"
  route_table_id              = oci_core_route_table.private_rt.id
  security_list_ids           = [oci_core_security_list.private_sl.id]
  prohibit_public_ip_on_vnic  = true
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp_options_id
}

resource "oci_core_subnet" "app" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.2.0/24"
  display_name                = "${var.label_prefix}-app"
  route_table_id              = oci_core_route_table.private_rt.id
  security_list_ids           = [oci_core_security_list.private_sl.id]
  prohibit_public_ip_on_vnic  = true
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp_options_id
}

resource "oci_core_subnet" "db1" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.3.0/24"
  display_name                = "${var.label_prefix}-db1"
  route_table_id              = oci_core_route_table.private_rt.id
  security_list_ids           = [oci_core_security_list.private_sl.id]
  prohibit_public_ip_on_vnic  = true
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp_options_id
}

resource "oci_core_subnet" "db2" {
  vcn_id                      = oci_core_vcn.vcn.id
  availability_domain         = null
  cidr_block                  = "10.0.4.0/24"
  display_name                = "${var.label_prefix}-db2"
  route_table_id              = oci_core_route_table.private_rt.id
  security_list_ids           = [oci_core_security_list.private_sl.id]
  prohibit_public_ip_on_vnic  = true
  dhcp_options_id             = oci_core_vcn.vcn.default_dhcp_options_id
}

resource "oci_core_network_security_group" "nsg_lb" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-nsg-lb"
}

resource "oci_core_network_security_group" "nsg_web" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-nsg-web"
}

resource "oci_core_network_security_group" "nsg_app" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-nsg-app"
}

resource "oci_core_network_security_group" "nsg_db" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-nsg-db"
}

resource "oci_core_network_security_group_security_rule" "lb_ingress_http" {
  network_security_group_id = oci_core_network_security_group.nsg_lb.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source                    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_ingress_https" {
  network_security_group_id = oci_core_network_security_group.nsg_lb.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source                    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      min = 443
      max = 443
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_web_http" {
  network_security_group_id = oci_core_network_security_group.nsg_lb.id
  direction                 = "EGRESS"
  protocol                  = "6"
  destination               = "10.0.1.0/24"
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_web_ephemeral" {
  network_security_group_id = oci_core_network_security_group.nsg_lb.id
  direction                 = "EGRESS"
  protocol                  = "6"
  destination               = "10.0.1.0/24"
  tcp_options {
    destination_port_range {
      min = 1024
      max = 65535
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_ingress_lb_http" {
  network_security_group_id = oci_core_network_security_group.nsg_web.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source                    = "10.0.0.0/24"
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_app" {
  network_security_group_id = oci_core_network_security_group.nsg_web.id
